# views.py - Django REST Framework API for generating personalized reports
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework import status
from django.template import Template, Context
from django.conf import settings
import logging
import re

logger = logging.getLogger(__name__)


class ReportTemplateView(APIView):
    """API endpoint for rendering custom report templates.

    Users can submit template strings with placeholders that get
    rendered with their account data for personalized reports.
    """
    permission_classes = [IsAuthenticated]

    ALLOWED_VARIABLES = ['username', 'email', 'department', 'report_date', 'total_hours']

    def _sanitize_template(self, template_str):
        """Basic sanitization - remove obvious script tags and limit length."""
        if len(template_str) > 5000:
            raise ValueError("Template too long")
        # Remove script tags
        template_str = re.sub(r'<script[^>]*>.*?</script>', '', template_str, flags=re.DOTALL | re.IGNORECASE)
        # Remove on* event handlers
        template_str = re.sub(r'\bon\w+\s*=', '', template_str, flags=re.IGNORECASE)
        return template_str

    def _get_user_context(self, user):
        """Build context dictionary from authenticated user."""
        return {
            'username': user.username,
            'email': user.email,
            'department': getattr(user, 'department', 'Engineering'),
            'report_date': '2024-01-15',
            'total_hours': 160,
            'settings': settings,  # Exposed for footer branding
        }

    def post(self, request):
        """Render a user-supplied template with account context.

        Request body:
            {"template": "Hello {{ username }}, your report for {{ report_date }}..."}
        """
        template_str = request.data.get('template', '')

        if not template_str:
            return Response(
                {'error': 'Template string is required'},
                status=status.HTTP_400_BAD_REQUEST
            )

        try:
            template_str = self._sanitize_template(template_str)
        except ValueError as e:
            return Response({'error': str(e)}, status=status.HTTP_400_BAD_REQUEST)

        try:
            # Render the Django template with user context
            context_data = self._get_user_context(request.user)
            template = Template(template_str)
            context = Context(context_data)
            rendered = template.render(context)

            logger.info(f"Report rendered for user {request.user.username}")
            return Response({'rendered': rendered})

        except Exception as e:
            logger.error(f"Template rendering error: {e}")
            return Response(
                {'error': 'Template rendering failed', 'detail': str(e)},
                status=status.HTTP_500_INTERNAL_SERVER_ERROR
            )


class TemplatePreviewView(APIView):
    """Preview endpoint - renders template without saving."""
    permission_classes = [IsAuthenticated]

    def post(self, request):
        template_str = request.data.get('template', '')
        preview_data = {
            'username': 'preview_user',
            'email': 'preview@example.com',
            'department': 'Preview',
            'report_date': '2024-01-01',
            'total_hours': 0,
            'settings': settings,
        }

        try:
            template = Template(template_str)
            context = Context(preview_data)
            rendered = template.render(context)
            return Response({'preview': rendered})
        except Exception as e:
            return Response(
                {'error': f'Preview failed: {str(e)}'},
                status=status.HTTP_400_BAD_REQUEST
            )


